messages.simulator-sample-code:
settings {
    name = "hello"
    version = "1.0.0"
    author = "you"
}

on<MKPlayerJoinEvent> {
    player.sendMessage("<green>Welcome, ${player.name}!</green>".parse())
    player.sendMessage("<gray>Type <yellow>/hello</yellow> to say hi.</gray>".parse())
}

command("hello", description = "Say hello", aliases = listOf("hi")) {
    executes {
        reply("<yellow>Hello from ${descriptor.name}!</yellow>")
        reply("<gray>This script is running live in your browser.</gray>")
    }
}

onUnload {
    info("hello unloaded")
}
